#!/usr/bin/env node

/**
 * V0 Project Detector
 *
 * Detects if a project was generated by Vercel V0 based on:
 * - Package dependencies
 * - Project structure
 * - Configuration files
 * - Import patterns
 *
 * Usage:
 *   node v0-detector.js /path/to/project
 *   node v0-detector.js . (current directory)
 */

const fs = require('fs').promises
const path = require('path')

class V0Detector {
  constructor(projectRoot) {
    this.projectRoot = projectRoot
    this.indicators = {
      strong: 0,
      medium: 0,
      weak: 0
    }
    this.findings = []
  }

  /**
   * Main detection method
   */
  async detect() {
    try {
      await this.checkPackageJson()
      await this.checkComponentStructure()
      await this.checkConfigurations()
      await this.checkImportPatterns()

      const confidence = this.calculateConfidence()

      return {
        isV0Generated: confidence >= 0.7,
        confidence: confidence,
        indicators: this.findings,
        score: {
          strong: this.indicators.strong,
          medium: this.indicators.medium,
          weak: this.indicators.weak
        }
      }
    } catch (error) {
      console.error('Detection error:', error)
      return {
        isV0Generated: false,
        confidence: 0,
        error: error.message
      }
    }
  }

  /**
   * Check package.json for V0-related dependencies
   */
  async checkPackageJson() {
    try {
      const packagePath = path.join(this.projectRoot, 'package.json')
      const content = await fs.readFile(packagePath, 'utf-8')
      const pkg = JSON.parse(content)

      // Check for Next.js
      if (pkg.dependencies?.next) {
        this.indicators.strong += 2
        this.findings.push({
          type: 'strong',
          message: `Next.js v${pkg.dependencies.next} detected`,
          file: 'package.json'
        })
      }

      // Check for shadcn/ui dependencies
      const shadcnIndicators = [
        '@radix-ui/react-dialog',
        '@radix-ui/react-dropdown-menu',
        '@radix-ui/react-select',
        '@radix-ui/react-label',
        '@radix-ui/react-slot',
        'lucide-react',
        'tailwindcss-animate',
        'class-variance-authority'
      ]

      let shadcnCount = 0
      const foundShadcn = []

      shadcnIndicators.forEach(dep => {
        if (pkg.dependencies?.[dep]) {
          shadcnCount++
          foundShadcn.push(dep)
        }
      })

      if (shadcnCount >= 4) {
        this.indicators.strong += 2
        this.findings.push({
          type: 'strong',
          message: `${shadcnCount} shadcn/ui dependencies detected: ${foundShadcn.slice(0, 3).join(', ')}${shadcnCount > 3 ? '...' : ''}`,
          file: 'package.json'
        })
      } else if (shadcnCount >= 2) {
        this.indicators.medium += 1
        this.findings.push({
          type: 'medium',
          message: `${shadcnCount} shadcn/ui dependencies detected`,
          file: 'package.json'
        })
      }

      // Check for Tailwind
      if (pkg.devDependencies?.tailwindcss) {
        this.indicators.medium += 1
        this.findings.push({
          type: 'medium',
          message: `Tailwind CSS v${pkg.devDependencies.tailwindcss} detected`,
          file: 'package.json'
        })
      }

      // Check for clsx + tailwind-merge (V0 pattern)
      if (pkg.dependencies?.clsx && pkg.dependencies?.['tailwind-merge']) {
        this.indicators.medium += 1
        this.findings.push({
          type: 'medium',
          message: 'clsx + tailwind-merge utility pattern detected (typical of V0)',
          file: 'package.json'
        })
      }

      // Check React version (18+ typical for V0)
      if (pkg.dependencies?.react) {
        const majorVersion = parseInt(pkg.dependencies.react.match(/\d+/)?.[0] || '0')
        if (majorVersion >= 18) {
          this.indicators.weak += 0.5
          this.findings.push({
            type: 'weak',
            message: `React v${pkg.dependencies.react} (18+ typical for V0)`,
            file: 'package.json'
          })
        }
      }
    } catch (error) {
      // package.json not found or invalid
    }
  }

  /**
   * Check for typical V0 component structure
   */
  async checkComponentStructure() {
    try {
      // Check for /components/ui directory (strong V0 indicator)
      const uiPath = path.join(this.projectRoot, 'components', 'ui')
      try {
        const files = await fs.readdir(uiPath)
        const tsxFiles = files.filter(f => f.endsWith('.tsx') || f.endsWith('.ts'))

        if (tsxFiles.length > 0) {
          this.indicators.strong += 1
          this.findings.push({
            type: 'strong',
            message: `shadcn/ui components directory found with ${tsxFiles.length} components`,
            file: 'components/ui/',
            examples: tsxFiles.slice(0, 3)
          })
        }
      } catch (e) {
        // Directory doesn't exist
      }

      // Check for kebab-case naming in components
      const componentsPath = path.join(this.projectRoot, 'components')
      try {
        const entries = await fs.readdir(componentsPath, { withFileTypes: true })
        const files = entries.filter(e => !e.isDirectory())

        const kebabFiles = files.filter(f => {
          // kebab-case pattern: lowercase with hyphens
          return /^[a-z][a-z0-9]*(-[a-z0-9]+)*\.(tsx|ts)$/.test(f.name)
        })

        if (kebabFiles.length >= 3) {
          this.indicators.medium += 1
          this.findings.push({
            type: 'medium',
            message: `kebab-case component naming pattern detected (${kebabFiles.length} files)`,
            file: 'components/',
            examples: kebabFiles.slice(0, 3).map(f => f.name)
          })
        }
      } catch (e) {
        // Directory doesn't exist
      }

      // Check for app directory (Next.js App Router)
      const appPath = path.join(this.projectRoot, 'app')
      try {
        await fs.access(appPath)
        this.indicators.medium += 1
        this.findings.push({
          type: 'medium',
          message: 'Next.js App Router directory found (app/)',
          file: 'app/'
        })
      } catch (e) {
        // Directory doesn't exist
      }
    } catch (error) {
      // Error checking structure
    }
  }

  /**
   * Check for configuration files (components.json, tailwind.config.ts, etc.)
   */
  async checkConfigurations() {
    try {
      // Check for components.json (strongest V0 indicator)
      const componentsJsonPath = path.join(this.projectRoot, 'components.json')
      try {
        const content = await fs.readFile(componentsJsonPath, 'utf-8')
        const json = JSON.parse(content)

        this.indicators.strong += 2
        this.findings.push({
          type: 'strong',
          message: 'components.json found (shadcn/ui CLI configuration)',
          file: 'components.json',
          details: {
            style: json.style,
            tsx: json.tsx,
            rsc: json.rsc,
            hasAliases: !!json.aliases
          }
        })
      } catch (e) {
        // File not found or invalid JSON
      }

      // Check for tailwind.config.ts
      try {
        const tailwindPath = path.join(this.projectRoot, 'tailwind.config.ts')
        await fs.access(tailwindPath)
        this.indicators.medium += 1
        this.findings.push({
          type: 'medium',
          message: 'tailwind.config.ts file found',
          file: 'tailwind.config.ts'
        })
      } catch (e) {
        // File not found
      }

      // Check tsconfig.json for path aliases
      try {
        const tsconfigPath = path.join(this.projectRoot, 'tsconfig.json')
        const content = await fs.readFile(tsconfigPath, 'utf-8')
        const tsconfig = JSON.parse(content)

        if (tsconfig.compilerOptions?.paths?.['@/*']) {
          this.indicators.medium += 1
          this.findings.push({
            type: 'medium',
            message: 'Path aliases (@/) configured in tsconfig.json (V0/Next.js pattern)',
            file: 'tsconfig.json',
            paths: Object.keys(tsconfig.compilerOptions.paths)
          })
        }
      } catch (error) {
        // File not found or invalid JSON
      }

      // Check next.config.js
      try {
        const nextConfigPath = path.join(this.projectRoot, 'next.config.js')
        await fs.access(nextConfigPath)
        this.indicators.weak += 0.5
        this.findings.push({
          type: 'weak',
          message: 'next.config.js found',
          file: 'next.config.js'
        })
      } catch (e) {
        // File not found
      }
    } catch (error) {
      // Error checking configurations
    }
  }

  /**
   * Check for V0-specific import patterns in component files
   */
  async checkImportPatterns() {
    const v0Patterns = [
      {
        pattern: /from ["']lucide-react["']/,
        name: 'Lucide React icons',
        weight: 'medium'
      },
      {
        pattern: /from ["']@\/components\/ui\//,
        name: 'shadcn/ui component imports',
        weight: 'strong'
      },
      {
        pattern: /^["']use client["']/m,
        name: 'React Server Components ("use client" directive)',
        weight: 'medium'
      },
      {
        pattern: /from ["']next\/link["']/,
        name: 'Next.js Link component',
        weight: 'weak'
      },
      {
        pattern: /from ["']next\/image["']/,
        name: 'Next.js Image component',
        weight: 'weak'
      },
      {
        pattern: /from ["']clsx["']/,
        name: 'clsx utility import',
        weight: 'weak'
      }
    ]

    try {
      const componentsPath = path.join(this.projectRoot, 'components')
      const files = await this.getAllTsxFiles(componentsPath)

      const patternMatches = new Map()

      for (const file of files.slice(0, 15)) { // Sample first 15 files
        try {
          const content = await fs.readFile(file, 'utf-8')

          for (const { pattern, name, weight } of v0Patterns) {
            if (pattern.test(content)) {
              if (!patternMatches.has(name)) {
                const weightValue = weight === 'strong' ? 1 : weight === 'medium' ? 0.5 : 0.25
                this.indicators[weight === 'strong' ? 'strong' : weight === 'medium' ? 'medium' : 'weak'] += weightValue
                patternMatches.set(name, true)
              }
            }
          }
        } catch (e) {
          // Error reading file
        }
      }

      for (const [name] of patternMatches) {
        const patternInfo = v0Patterns.find(p => p.name === name)
        this.findings.push({
          type: patternInfo?.weight || 'weak',
          message: `${name} pattern detected in components`,
          file: 'components/*'
        })
      }
    } catch (error) {
      // Components directory not found
    }
  }

  /**
   * Recursively get all TSX/TS files in a directory
   */
  async getAllTsxFiles(dir) {
    const files = []

    try {
      const entries = await fs.readdir(dir, { withFileTypes: true })

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name)

        if (entry.isDirectory()) {
          const subfiles = await this.getAllTsxFiles(fullPath)
          files.push(...subfiles)
        } else if (entry.name.endsWith('.tsx') || entry.name.endsWith('.ts')) {
          files.push(fullPath)
        }
      }
    } catch (error) {
      // Error reading directory
    }

    return files
  }

  /**
   * Calculate confidence score (0-1)
   */
  calculateConfidence() {
    const total =
      this.indicators.strong * 2 +
      this.indicators.medium * 1 +
      this.indicators.weak * 0.5

    // Normalize to 0-1 scale
    const maxScore = 15 // Reasonable max for typical V0 projects
    return Math.min(total / maxScore, 1.0)
  }
}

/**
 * Format and display results
 */
function displayResults(result, projectRoot) {
  console.log('\n╔════════════════════════════════════════════════════════╗')
  console.log('║          V0 PROJECT DETECTION RESULTS                  ║')
  console.log('╚════════════════════════════════════════════════════════╝\n')

  console.log(`Project Root: ${projectRoot}`)
  console.log(`Detection Status: ${result.isV0Generated ? '✓ V0 Project' : '✗ Not a V0 Project'}`)
  console.log(`Confidence Score: ${(result.confidence * 100).toFixed(1)}%\n`)

  if (result.error) {
    console.log(`Error: ${result.error}\n`)
    return
  }

  console.log('Detected Indicators:')
  console.log('─────────────────────────────────────────────────────────\n')

  // Group by type
  const byType = {
    strong: [],
    medium: [],
    weak: []
  }

  result.indicators.forEach(indicator => {
    byType[indicator.type].push(indicator)
  })

  // Display strong indicators
  if (byType.strong.length > 0) {
    console.log('STRONG INDICATORS (Definitive V0 markers):')
    byType.strong.forEach(ind => {
      console.log(`  ✓ ${ind.message}`)
      if (ind.file) console.log(`    File: ${ind.file}`)
      if (ind.examples) console.log(`    Examples: ${ind.examples.join(', ')}`)
      if (ind.details) {
        Object.entries(ind.details).forEach(([key, value]) => {
          console.log(`    ${key}: ${value}`)
        })
      }
    })
    console.log()
  }

  // Display medium indicators
  if (byType.medium.length > 0) {
    console.log('MEDIUM INDICATORS (Supporting V0 evidence):')
    byType.medium.forEach(ind => {
      console.log(`  ○ ${ind.message}`)
      if (ind.file) console.log(`    File: ${ind.file}`)
      if (ind.examples) console.log(`    Examples: ${ind.examples.join(', ')}`)
    })
    console.log()
  }

  // Display weak indicators
  if (byType.weak.length > 0) {
    console.log('WEAK INDICATORS (Common but not definitive):')
    byType.weak.forEach(ind => {
      console.log(`  · ${ind.message}`)
      if (ind.file) console.log(`    File: ${ind.file}`)
    })
    console.log()
  }

  // Score breakdown
  console.log('Score Breakdown:')
  console.log('─────────────────────────────────────────────────────────')
  console.log(`  Strong Indicators:  ${result.score.strong}`)
  console.log(`  Medium Indicators:  ${result.score.medium}`)
  console.log(`  Weak Indicators:    ${result.score.weak}`)
  console.log()

  // Recommendation
  console.log('Interpretation:')
  console.log('─────────────────────────────────────────────────────────')
  if (result.confidence >= 0.9) {
    console.log('✓ VERY LIKELY a V0-generated project')
  } else if (result.confidence >= 0.7) {
    console.log('✓ LIKELY a V0-generated project')
  } else if (result.confidence >= 0.5) {
    console.log('◆ POSSIBLY a V0-inspired project (Next.js + shadcn/ui)')
  } else if (result.confidence >= 0.3) {
    console.log('◇ SOME V0-related characteristics detected')
  } else {
    console.log('✗ NOT likely a V0-generated project')
  }
  console.log()
}

/**
 * Main entry point
 */
async function main() {
  const args = process.argv.slice(2)
  const projectRoot = args[0] || '.'

  try {
    // Verify project exists
    await fs.access(projectRoot)
  } catch (error) {
    console.error(`Error: Project root not found: ${projectRoot}`)
    process.exit(1)
  }

  const detector = new V0Detector(projectRoot)
  const result = await detector.detect()

  displayResults(result, projectRoot)

  // Exit with appropriate code
  process.exit(result.isV0Generated ? 0 : 1)
}

// Run if executed directly
if (require.main === module) {
  main().catch(err => {
    console.error('Fatal error:', err)
    process.exit(1)
  })
}

module.exports = V0Detector
